def is_not_prime(n):
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(nums, n):
    return heapq.nlargest(n, nums)

def differ_At_One_Bit_Pos(a, b):
    x = a ^ b
    return x != 0 and (x & (x - 1)) == 0

import re

def find_char_long(text):
    return re.findall(r"\b\w{4,}\b", text)

def find_Rotations(s):
    if not s:
        return 0
    return (s + s).find(s, 1)

def remove_Occ(string, char):
    first = string.find(char)
    if first == -1 or char == "":
        return string

    last = string.rfind(char)

    if first == last:
        return string[:first] + string[first + len(char):]

    return string[:first] + string[first + len(char):last] + string[last + len(char):]

import re

def text_lowercase_underscore(text):
    return bool(re.fullmatch(r"[a-z]+_[a-z]+", text))

def remove_dirty_chars(string, dirty_chars):
    dirty_set = set(dirty_chars)
    return "".join(char for char in string if char not in dirty_set)

def is_woodall(num):
    if not isinstance(num, int) or num < 1:
        return False

    n = 1
    while True:
        woodall = n * (2 ** n) - 1
        if woodall == num:
            return True
        if woodall > num:
            return False
        n += 1

def check(n):
    rev = int(str(abs(n))[::-1])
    if n < 0:
        rev = -rev
    return n == 2 * rev - 1

def count_Substrings(s):
    count = {0: 1}
    prefix_sum = 0
    result = 0

    for ch in s:
        prefix_sum += int(ch) - 1
        result += count.get(prefix_sum, 0)
        count[prefix_sum] = count.get(prefix_sum, 0) + 1

    return result

def recursive_list_sum(lst):
    if isinstance(lst, (list, tuple)):
        return sum(recursive_list_sum(item) for item in lst)
    return lst

def bell_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    row = [1]
    for i in range(1, n + 1):
        new_row = [row[-1]]
        for j in range(1, i + 1):
            new_row.append(new_row[j - 1] + row[j - 1])
        row = new_row

    return row[0]

def is_sublist(lst, sublst):
    if not sublst:
        return True
    if len(sublst) > len(lst):
        return False

    n = len(sublst)
    for i in range(len(lst) - n + 1):
        if lst[i:i + n] == sublst:
            return True
    return False

def comb_sort(elements):
    arr = list(elements)
    gap = len(arr)
    shrink = 1.3
    swapped = True

    while gap > 1 or swapped:
        gap = max(1, int(gap / shrink))
        swapped = False

        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

    return True

import math

def volume_sphere(radius):
    return (4 / 3) * math.pi * radius ** 3

def sequence(n):
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n <= 2:
        return 1

    a = [0] * (n + 1)
    a[1] = a[2] = 1

    for i in range(3, n + 1):
        prev = a[i - 1]
        a[i] = a[prev] + a[i - prev]

    return a[n]

import math

def surfacearea_sphere(radius):
    return 4 * math.pi * radius ** 2

def merge_dictionaries_three(dict1, dict2, dict3):
    result = {}
    for d in (dict1, dict2, dict3):
        for key, value in d.items():
            if key not in result:
                result[key] = value
    return result

def freq_count(lst):
    freq = {}
    for item in lst:
        freq[item] = freq.get(item, 0) + 1
    return freq

def is_undulating(n):
    s = str(n)
    if s.startswith("-"):
        return False
    if len(s) < 3:
        return False
    if s[0] == s[1]:
        return False
    return all(s[i] == s[i % 2] for i in range(len(s)))

def divisor(n):
    n = abs(n)
    if n == 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 1 if i * i == n else 2
        i += 1

    return count

def frequency_lists(list_of_lists):
    frequencies = {}
    for sublist in list_of_lists:
        for element in sublist:
            frequencies[element] = frequencies.get(element, 0) + 1
    return frequencies

def multiply_num(nums):
    product = 1
    for num in nums:
        product *= num
    return product / len(nums)

def decimal_to_binary(n):
    if n == 0:
        return "0"
    if n < 0:
        return "-" + decimal_to_binary(-n)

    binary = ""
    while n > 0:
        binary = str(n % 2) + binary
        n //= 2
    return binary

def next_smallest_palindrome(num):
    target = num + 1

    if target <= 0:
        return 0

    s = str(target)
    length = len(s)
    half = (length + 1) // 2

    def make_palindrome(prefix, total_length):
        if total_length % 2 == 0:
            return prefix + prefix[::-1]
        return prefix + prefix[-2::-1]

    prefix = s[:half]
    palindrome = make_palindrome(prefix, length)

    if int(palindrome) >= target:
        return int(palindrome)

    prefix = str(int(prefix) + 1)

    if len(prefix) > half:
        return int("1" + ("0" * (length - 1)) + "1")

    return int(make_palindrome(prefix, length))

def eulerian_num(n, m):
    if n < 0 or m < 0:
        return 0
    if n == 0:
        return 1 if m == 0 else 0
    if m >= n:
        return 0

    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(0, min(i, m + 1)):
            val = 0
            if j > 0:
                val += (i - j) * dp[i - 1][j - 1]
            val += (j + 1) * dp[i - 1][j]
            dp[i][j] = val

    return dp[n][m]

def odd_Equivalent(s, n):
    if not s or n <= 0:
        return 0

    length = len(s)
    full_cycles, remainder = divmod(n, length)
    return full_cycles * s.count('1') + s[:remainder].count('1')

def common_in_nested_lists(nested_lists):
    if not nested_lists:
        return []

    common = set(nested_lists[0])
    for sublist in nested_lists[1:]:
        common &= set(sublist)
        if not common:
            return []

    result = []
    seen = set()
    for item in nested_lists[0]:
        if item in common and item not in seen:
            result.append(item)
            seen.add(item)

    return result

def check_integer(s):
    if not isinstance(s, str):
        return False

    s = s.strip()
    if not s:
        return False

    if s[0] in "+-":
        return len(s) > 1 and s[1:].isdigit()

    return s.isdigit()

def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if mid % 2 == 1:
            mid -= 1

        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid

    return arr[left]

def amicable_numbers_sum(n):
    if n < 2:
        return 0

    divisor_sums = [0] * (n + 1)
    for divisor in range(1, n // 2 + 1):
        for multiple in range(divisor * 2, n + 1, divisor):
            divisor_sums[multiple] += divisor

    memo = {}

    def sum_proper_divisors(x):
        if x <= n:
            return divisor_sums[x]
        if x in memo:
            return memo[x]

        original = x
        total = 1

        p = 2
        while p * p <= x:
            if x % p == 0:
                term = 1
                power = 1
                while x % p == 0:
                    x //= p
                    power *= p
                    term += power
                total *= term
            p += 1 if p == 2 else 2

        if x > 1:
            total *= (1 + x)

        memo[original] = total - original
        return memo[original]

    total_sum = 0
    for a in range(2, n + 1):
        b = divisor_sums[a]
        if b != a and b > 0 and sum_proper_divisors(b) == a:
            total_sum += a

    return total_sum

import cmath

def angle_complex(real, imag):
    if isinstance(imag, complex):
        z = real + imag
    else:
        z = complex(real, imag)
    return cmath.phase(z)

def find_length(string):
    if not string:
        return 0

    max_diff = float("-inf")
    current = 0

    for ch in string:
        value = 1 if ch == "0" else -1
        current = max(value, current + value)
        max_diff = max(max_diff, current)

    return max_diff

import math

def sum(a, b):
    g = math.gcd(abs(a), abs(b))
    if g == 0:
        return 0

    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1

    return total

def magic_square_test(matrix):
    if not matrix or not isinstance(matrix, list):
        return False

    n = len(matrix)

    if any(not isinstance(row, list) or len(row) != n for row in matrix):
        return False

    target = sum(matrix[0])

    for row in matrix:
        if sum(row) != target:
            return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True
